# Scan transcript_full.jsonl for database or backend settings
$logPath = "C:\Users\gowth\.gemini\antigravity\brain\57f84777-eccc-4ac2-98d4-605734965dd4\.system_generated\logs\transcript_full.jsonl"

if (Test-Path $logPath) {
    $lines = Get-Content $logPath
    $matches = @()
    foreach ($line in $lines) {
        if ($line -like "*mongodb*" -or $line -like "*backend*" -or $line -like "*2515*" -or $line -like "*MONGO*") {
            $matches += $line
        }
    }
    Write-Host "Found $($matches.Count) matching lines."
    $matches | Select-Object -Last 10 | Out-File -FilePath "C:\Users\gowth\Videos\Project\Photography\client_photography\db_scan.json" -Encoding utf8
} else {
    Write-Host "Log file NOT found"
}
